import { useNoticeListInfiniteQuery } from '~/entities/community/api/use-notice-list-infinite-query';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';

export const NoticeMenuButton = () => {
  const { navigate } = useNavigate();
  const { data: list } = useNoticeListInfiniteQuery({
    paging: {
      currentPageNo: 1,
      recordCountPerPage: 99999999,
    },
  });

  const hasUnreadNotices = list?.pages[0]?.result?.list.some((notice) => !notice.isRead);

  return (
    <button
      type="button"
      className={`menu-btn no-icon ${hasUnreadNotices ? 'add-alert' : ''}`}
      onClick={() => {
        navigate(PATHS.community.notice);
      }}
    >
      <span className="menu-btn-text">{i18n.t('notice')}</span>
    </button>
  );
};
