import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { appConfig } from '~/shared/config';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';

export const MyBankAccountMenuButton = () => {
  const { data: userRes } = useGetUserInfoQuery();
  const hasWallet = !!userRes?.tbCstmrMastr?.hasWallet;
  const { shortBankName } = useComBankInfo(appConfig.BANK_CODE ?? '');
  const { navigate } = useNavigate();
  if (!hasWallet) {
    return <></>;
  }
  return (
    <button
      type="button"
      className="menu-btn"
      onClick={() => {
        navigate(PATHS.account.myBankAccount);
      }}
    >
      <span className="menu-btn-text">{i18n.t('checkLinkedAccount')}</span>
      <span className="btn-info">
        {shortBankName} {userRes?.tbCstmrMastr?.realAcnutNo}
      </span>
    </button>
  );
};
