import i18n from '~/shared/i18n/i18n';
import { overlay } from '~/shared/lib/overlay';
import { Dialog } from '~/shared/ui/dialogs/dialog';
import { AgreementDialogContent } from './agreement-dialog-content';

export const AgreementMenuButton = () => {
  const handleClick = () => {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog
          afterLeave={unmount}
          open={isOpen}
          onClose={close}
          fullScreenMode
          message={<AgreementDialogContent />}
        />
      );
    });
  };

  return (
    <button type="button" className="menu-btn" onClick={handleClick}>
      <span className="menu-btn-text">{i18n.t('privacyPolicy')}</span>
    </button>
  );
};
